import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"小学三年级数学：知识讲解 · 八个方向与观察物体至单价数量、速度时间与两步应用","description":"小学三年级数学 20 个知识点，包含定义、方法、例题、易错与本地图示。","frontmatter":{"title":"小学三年级数学：知识讲解 · 八个方向与观察物体至单价数量、速度时间与两步应用","description":"小学三年级数学 20 个知识点，包含定义、方法、例题、易错与本地图示。","splitFrom":"life/math/primary/grade-3/knowledge.md","showdocs":{"topics":[{"id":"math","title":"数学","link":"/topics/math/"}],"kind":"知识讲解","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"小学三年级数学：知识讲解","summary":"小学三年级数学 20 个知识点，包含定义、方法、例题、易错与本地图示。","status":"active","related":[{"title":"八年级数学独立习题集","link":"/life/math/junior/grade-8/exercises","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学独立习题集 · 平方根、立方根与实数至一次函数与实际方案比较","link":"/life/math/junior/grade-8/exercises-part-01","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学独立习题集 · 三角形全等与对应关系至加权平均数与方差","link":"/life/math/junior/grade-8/exercises-part-02","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学公式速查","link":"/life/math/junior/grade-8/formulas","kind":"公式与参考","scope":"general","audience":"general"},{"title":"程序员数学 11：文件处理任务的数学复盘","link":"/life/math/programmer/practice","kind":"习题与解析","scope":"general","audience":"general"}],"prev":{"text":"小学三年级数学：知识讲解 · 多位数乘一位数至年、月、日与闰年","link":"/life/math/primary/grade-3/knowledge-part-01"},"next":{"text":"小学三年级数学：公式与规则速查","link":"/life/math/primary/grade-3/formulas"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"小学三年级数学：知识讲解 · 多位数乘一位数至年、月、日与闰年","link":"/life/math/primary/grade-3/knowledge-part-01"},"next":{"text":"小学三年级数学：公式与规则速查","link":"/life/math/primary/grade-3/formulas"}},"headers":[],"relativePath":"life/math/primary/grade-3/knowledge-part-02.md","filePath":"life/math/primary/grade-3/knowledge-part-02.md"}'),p={name:"life/math/primary/grade-3/knowledge-part-02.md"};function n(o,e,s,l,g,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="小学三年级数学-知识讲解-·-八个方向与观察物体至单价数量、速度时间与两步应用" tabindex="-1">小学三年级数学：知识讲解 · 八个方向与观察物体至单价数量、速度时间与两步应用 <a class="header-anchor" href="#小学三年级数学-知识讲解-·-八个方向与观察物体至单价数量、速度时间与两步应用" aria-label="Permalink to &quot;小学三年级数学：知识讲解 · 八个方向与观察物体至单价数量、速度时间与两步应用&quot;">​</a></h1><p><a href="/life/math/primary/grade-3/knowledge">返回分篇目录</a></p><p><a href="/life/math/primary/grade-3/knowledge">知识讲解</a> · <a href="/life/math/primary/grade-3/formulas">公式速查</a> · <a href="/life/math/primary/grade-3/exercises">独立习题集</a></p><p>按六三三学段编排的通用建议学习顺序；不同地区、教材和学期安排存在差异。本版覆盖以下明确列出的知识点，不将其等同于所有教材或完整课程标准。</p><h2 id="p3-16" tabindex="-1">八个方向与观察物体 <a class="header-anchor" href="#p3-16" aria-label="Permalink to &quot;八个方向与观察物体 {#p3-16}&quot;">​</a></h2><p><strong>定义与条件：</strong> 地图常按上北下南、左西右东表示方向，四个中间方向是东北、东南、西南、西北。从不同方向看同一物体，看到的轮廓可能不同。</p><p><strong>方法：</strong> 先固定地图的北向，再判断相对位置；观察立体积木时分别记录正面、侧面、上面能看到的形状。</p><p><strong>例子：</strong> 学校在广场东北方，则广场在学校西南方；两个正方体上下叠放，从正面看是上下两格，从上面看是一格。</p><p><strong>易错：</strong> 反向描述要换成相反方向；上面看不到下层积木，并不代表它不存在。</p><p><a href="/life/math/primary/grade-3/formulas#p3-16">对应公式</a> · <a href="/life/math/primary/grade-3/exercises#p3-16">练习题组</a></p><h2 id="p3-17" tabindex="-1">复式统计表与数据比较 <a class="header-anchor" href="#p3-17" aria-label="Permalink to &quot;复式统计表与数据比较 {#p3-17}&quot;">​</a></h2><p><strong>定义与条件：</strong> 复式统计表在同一张表中按两个分类标准记录数据，例如年级与运动项目，便于横向、纵向比较。</p><p><strong>方法：</strong> 先读行标题、列标题及单位，再定位交叉处；合计之前确认类别没有重叠。</p><p><strong>例子：</strong> 三年级足球 8 人、篮球 6 人，四年级足球 10 人、篮球 9 人；足球合计 18 人，四年级两项合计 19 人。</p><p><strong>易错：</strong> 一行合计与一列合计含义不同；数据允许多选时不能直接当作总人数。</p><p><a href="/life/math/primary/grade-3/formulas#p3-17">对应公式</a> · <a href="/life/math/primary/grade-3/exercises#p3-17">练习题组</a></p><h2 id="p3-18" tabindex="-1">确定事件与可能性初步 <a class="header-anchor" href="#p3-18" aria-label="Permalink to &quot;确定事件与可能性初步 {#p3-18}&quot;">​</a></h2><p><strong>定义与条件：</strong> 有些事件一定发生，有些不可能发生，有些可能发生。随机抽取的结果不能预先确定；在每个物体被抽到机会相同的条件下，数量多的类别更容易抽到。</p><p><strong>方法：</strong> 先列出可能结果，再看袋中各类数量；区分“更可能”与“一定”。</p><p><strong>例子：</strong> 袋内有 4 个红球、1 个蓝球，充分混合后摸 1 个，摸红球更可能，但仍可能摸到蓝球。</p><p><strong>易错：</strong> 一次结果不能证明某种颜色“以后一定更多”；概率大小不保证每次结果。</p><p><a href="/life/math/primary/grade-3/formulas#p3-18">对应公式</a> · <a href="/life/math/primary/grade-3/exercises#p3-18">练习题组</a></p><h2 id="p3-19" tabindex="-1">排列、组合与不重复计数 <a class="header-anchor" href="#p3-19" aria-label="Permalink to &quot;排列、组合与不重复计数 {#p3-19}&quot;">​</a></h2><p><strong>定义与条件：</strong> 排列关注先后顺序，组合只关注选中了谁；解决简单计数可先固定一个对象，再有序列举。</p><p><strong>方法：</strong> 列两位数时先确定十位，十位不能是 0；统计两人配对时，甲乙与乙甲若代表同一对，只计一次。</p><p><strong>例子：</strong> 用 1、2、3 组成没有重复数字的两位数，十位有 3 选，个位各有 2 选，共 6 个。三人两两握手只需 3 次。</p><p><strong>易错：</strong> 是否计顺序由情境决定，不是见到两个对象就一律乘 2。</p><p><a href="/life/math/primary/grade-3/formulas#p3-19">对应公式</a> · <a href="/life/math/primary/grade-3/exercises#p3-19">练习题组</a></p><h2 id="p3-20" tabindex="-1">单价数量、速度时间与两步应用 <a class="header-anchor" href="#p3-20" aria-label="Permalink to &quot;单价数量、速度时间与两步应用 {#p3-20}&quot;">​</a></h2><p><strong>定义与条件：</strong> 总价来自每件价格与件数；匀速行程的路程来自单位时间所走距离与时间。这两类都是“每份量×份数”。</p><p><strong>方法：</strong> 明确每份量的单位，求中间量后再比较或合计；速度的时间单位必须与时间一致。</p><p><strong>例子：</strong> 每本 12 元买 8 本，总价 96 元；每小时走 4 千米，走 3 小时，路程 12 千米。</p><p><strong>易错：</strong> 不能把“元/本”和“千米/时”当作没有含义的数字；实际速度变化时不可随意套匀速关系。</p><p><a href="/life/math/primary/grade-3/formulas#p3-20">对应公式</a> · <a href="/life/math/primary/grade-3/exercises#p3-20">练习题组</a></p>',34)])])}const f=a(p,[["render",n]]);export{h as __pageData,f as default};
